$script=@'
import { chromium } from "@playwright/test";
const b = await chromium.launch();
const p = await (await b.newContext({ viewport:{width:390,height:844}})).newPage();
await p.goto("http://127.0.0.1:8095/#/pages/history/index", { waitUntil:"networkidle", timeout:60000 });
await p.waitForTimeout(2000);
const btn = p.getByRole("button", { name:/查看详情/ }).first();
if (await btn.count()) await btn.click();
await p.waitForTimeout(2000);
const sample = await p.$$eval(".detail-row-label", els => els.slice(0,5).map(el => {
  const cs = getComputedStyle(el);
  return { text: el.textContent.trim().slice(0,20), textOverflow: cs.textOverflow, whiteSpace: cs.whiteSpace, scrollW: el.scrollWidth, clientW: el.clientWidth, h: el.getBoundingClientRect().height };
}));
console.log(JSON.stringify(sample, null, 2));
await b.close();
